const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_WIDE';
pres.author = 'Our World in Data synthesis';
pres.subject = 'Vaccination impact and timelines';
pres.title = 'The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time';
pres.company = 'Public Health Briefing';
pres.lang = 'en-US';
pres.theme = {
  headFontFace: 'Arial',
  bodyFontFace: 'Arial',
  lang: 'en-US'
};

const theme = {
  primary: '0B1F3A',
  secondary: '1F4E79',
  accent: '00A3A3',
  light: 'EAF2FB',
  bg: 'F7FAFC',
  text: '1A1A1A',
  muted: '5B6573',
  success: '0B8F5A',
  warning: 'B06A00',
  danger: 'B42318'
};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, '0');
  require(`./slide-${num}.js`).createSlide(pres, theme);
}

pres.writeFile({ fileName: '/app/output/final_deck.pptx' });
EOF

