    x: 0.7, y: 1.15, w: 12, h: 1.2,
    fontFace: 'Arial', fontSize: 34, bold: true, color: theme.primary
  });
  slide.addText('A data-driven overview of vaccination impact and innovation (1796–2020)', {
    x: 0.7, y: 2.45, w: 11.6, h: 0.6,
    fontFace: 'Arial', fontSize: 18, color: theme.secondary
  });
  slide.addText('Audience: Public health professionals and policy analysts', {
    x: 0.7, y: 3.2, w: 10.5, h: 0.35, fontFace: 'Arial', fontSize: 13, color: theme.muted
