  slide.addText('Source attribution: Our World in Data (as compiled in source brief)', {
    x: 0.7, y: 5.1, w: 12, h: 0.3, fontFace: 'Arial', fontSize: 11, color: theme.muted, italic: true
  });
}
module.exports = { createSlide };
EOF

